// Etapa 2: Construir el texto publicable para la red social
const data = $input.first().json.body;

const user = data.user || `Donante #${data.donanteId}`;
const badge = data.badge || 'Insignia';
const description = data.description || 'Logro desbloqueado en DonaTrack';

const postText = `🏅 ¡${user} acaba de obtener la insignia "${badge}" en DonaTrack!\n\n${description}\n\n#DonaTrack #Donaciones #Solidaridad`;

return [{
  json: {
    donanteId: data.donanteId,
    user,
    badge,
    description,
    postText,
    timestamp: new Date().toISOString()
  }
}];

// Etapa 3: Simulación de generación de imagen
// En producción, aquí se llamaría a una API como DALL-E, Stable Diffusion, etc.
// Por ahora generamos una URL de imagen simulada.

const data = $input.first().json;

const imageUrl = `https://via.placeholder.com/800x400/FF6B35/FFFFFF?text=${encodeURIComponent(data.badge)}`;

console.log(`[MOCK] Imagen generada para insignia '${data.badge}': ${imageUrl}`);

return [{
  json: {
    ...data,
    imageUrl,
    imageGenerated: true
  }
}];

// Validar respuesta de la publicación simulada
const data = $input.first().json;

const publicado = data.url !== undefined; // httpbin devuelve la URL del request

console.log(`[MOCK] Publicación en red social: ${publicado ? 'EXITOSA' : 'FALLIDA'}`);

return [{
  json: {
    status: 'ok',
    publicado,
    mensaje: `Insignia '${$('Construir Texto Publicable').first().json.badge}' publicada correctamente (mock)`,
    timestamp: new Date().toISOString()
  }
}];
